import type { PieSeriesOption } from 'echarts/charts'
import type { ComposeOption } from 'echarts/core'

export type DonutDatum = { id: string; name: string; value: number; color: string }
export type DonutOption = ComposeOption<PieSeriesOption>
export const OUTER_LABEL_MINIMUM_RATIO = 0.01

/** ECharts 的 startAngle 使用角度，90° 表示从顶部开始；只旋转整个圆环，不单独搬动标签。 */
export function balancedStartAngle(values: readonly number[]): number {
  const total = values.reduce((sum, value) => sum + Math.max(0, value), 0)
  if (total <= 0 || values.length < 2) return 90
  let cursor = 0
  const items = values.filter((value) => value > 0).map((value) => {
    const ratio = value / total
    const middle = cursor + ratio * 180
    cursor += ratio * 360
    return { value, middle }
  })
  // 小于阈值的标签不会绘制，旋转时也不能占用“视觉位置”。
  const visibleItems = items.filter((item) => item.value / total >= OUTER_LABEL_MINIMUM_RATIO)
  const layoutItems = visibleItems.length >= 2 ? visibleItems : items
  let best = { angle: 90, score: Infinity }
  // 逐度搜索只需执行一次配置计算，能覆盖极小扇区跨越水平中线的边界情况。
  // 评分先尽量把实际可见标签分散到四个象限，再平衡左右数量。
  for (let angle = 0; angle < 360; angle += 1) {
    let left = 0
    const quadrants = [0, 0, 0, 0]
    for (const item of layoutItems) {
      const radians = (item.middle - angle) * Math.PI / 180
      const isLeft = Math.cos(radians) < 0
      const isBottom = Math.sin(radians) >= 0
      if (isLeft) left += 1
      quadrants[(isBottom ? 2 : 0) + (isLeft ? 0 : 1)] += 1
    }
    const countImbalance = Math.abs(layoutItems.length - 2 * left)
    const quadrantCrowding = quadrants.reduce((score, count) => score + Math.max(0, count - 1) ** 2, 0)
    const distanceFromTop = Math.min(Math.abs(angle - 90), 360 - Math.abs(angle - 90))
    const score = quadrantCrowding * 100 + countImbalance * 10 + distanceFromTop / 360
    if (score < best.score) best = { angle, score }
  }
  return best.angle
}

export function donutRadius(width: number, height: number): number {
  return Math.min(width * 0.30, height * 0.34, 170)
}

/**
 * 中间点以首尾连线的中点为基准，只沿扇区外法线做小幅偏移。
 * 这样形成完整的拱形曲线，而不是“先向外走一段、再横向转弯”的圆角折线。
 */
export function naturalCurveBend(
  start: readonly [number, number],
  end: readonly [number, number],
  width: number,
  height: number,
): [number, number] {
  const vectorX = start[0] - width / 2
  const vectorY = start[1] - height / 2
  const radialLength = Math.hypot(vectorX, vectorY)
  if (radialLength < 1) return [(start[0] + end[0]) / 2, (start[1] + end[1]) / 2]

  const labelDistance = Math.hypot(end[0] - start[0], end[1] - start[1])
  const reach = Math.min(22, Math.max(10, labelDistance * 0.1))
  return [
    (start[0] + end[0]) / 2 + vectorX / radialLength * reach,
    (start[1] + end[1]) / 2 + vectorY / radialLength * reach,
  ]
}

export function buildDonutOption(items: readonly DonutDatum[], width: number, height: number): DonutOption {
  // ECharts 的逐侧避让会优先保留先进入布局的标签；显式按占比降序，确保空间不足时优先保留大分类。
  const orderedItems = [...items].sort((a, b) => b.value - a.value)
  const radius = donutRadius(width, height)
  const total = orderedItems.reduce((sum, item) => sum + Math.max(0, item.value), 0)
  return {
    animation: false,
    series: [{
      type: 'pie',
      silent: true,
      selectedMode: false,
      emphasis: { disabled: true, scale: false },
      radius: [radius * 0.64, radius],
      center: ['50%', '50%'],
      startAngle: balancedStartAngle(orderedItems.map((item) => item.value)),
      clockwise: true,
      minAngle: 0,
      padAngle: 0,
      itemStyle: { borderWidth: 0 },
      avoidLabelOverlap: true,
      label: {
        show: true,
        position: 'outside',
        // 文字端点保持在安全边缘内；曲线形状只由 labelLayout 调整，不搬动文字本身。
        alignTo: 'edge',
        edgeDistance: 12,
        distanceToLabelLine: 6,
        minMargin: 8,
        overflow: 'none',
        fontSize: width < 360 ? 11 : 12,
        lineHeight: 16,
        color: 'inherit',
        formatter: ({ name, dataIndex }) => {
          return `${name} ${(orderedItems[dataIndex].value / total * 100).toFixed(1)}%`
        },
      },
      // 使用连续曲线和逐侧避让，扇区锚点与文字始终保留同一侧、相同顺序。
      labelLine: { length: 18, length2: 24, smooth: 0.45, maxSurfaceAngle: 80, lineStyle: { width: 1 } },
      labelLayout: (params) => {
        const points = params.labelLinePoints?.map(([pointX, pointY]) => [pointX, pointY])
        if (points && points.length >= 3) {
          const start = points[0]
          const end = points[points.length - 1]
          const bend = points[1]
          const naturalBend = naturalCurveBend(
            [start[0], start[1]],
            [end[0], end[1]],
            width,
            height,
          )
          bend[0] = naturalBend[0]
          bend[1] = naturalBend[1]
        }
        return {
          labelLinePoints: points,
          moveOverlap: 'shiftY',
          hideOverlap: true,
        }
      },
      data: orderedItems.map((item) => ({
        id: item.id,
        name: item.name,
        value: item.value,
        itemStyle: { color: item.color },
        // 外侧文案只承担主要分类的快速识别；小于 1% 的分类仍保留扇区与底部图例。
        label: { show: total > 0 && item.value / total >= OUTER_LABEL_MINIMUM_RATIO },
      })),
    }],
  }
}
