<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { Check, ChevronDown } from '@lucide/vue'

/** 报表卡片的分类层级：child=二级分类（默认，与旧版一致），parent=一级分类聚合 */
type CategoryLevel = 'child' | 'parent'

const props = defineProps<{ modelValue: CategoryLevel }>()
const emit = defineEmits<{ 'update:modelValue': [value: CategoryLevel] }>()

const labels: Record<CategoryLevel, string> = { parent: '一级分类', child: '二级分类' }
const options: readonly CategoryLevel[] = ['parent', 'child']
const open = ref(false)
const root = ref<HTMLElement>()

function close(event: PointerEvent): void {
  if (!root.value?.contains(event.target as Node)) open.value = false
}

onMounted(() => document.addEventListener('pointerdown', close))
onBeforeUnmount(() => document.removeEventListener('pointerdown', close))

function select(value: CategoryLevel): void {
  emit('update:modelValue', value)
  open.value = false
}
</script>

<template>
  <div ref="root" class="level-menu">
    <button class="level-trigger" type="button" aria-haspopup="menu" :aria-expanded="open" @click="open = !open">
      {{ labels[modelValue] }}<ChevronDown :size="15" aria-hidden="true" />
    </button>
    <div v-if="open" class="level-options" role="menu" aria-label="分类层级">
      <button v-for="item in options" :key="item" type="button" role="menuitemradio" :aria-checked="modelValue === item" @click="select(item)">
        <Check :size="17" :class="{ hidden: modelValue !== item }" aria-hidden="true" />
        <span :class="{ active: modelValue === item }">{{ labels[item] }}</span>
      </button>
    </div>
  </div>
</template>

<style scoped>
/* 交互与流水页顶部的天/周/月/年切换一致：点开下拉、点外部自动收起 */
.level-menu { position: relative; display: flex; align-items: center; justify-content: flex-end; }
.level-trigger { display: inline-flex; height: 36px; align-items: center; justify-content: center; gap: 2px; padding: 0 8px; border: 0; border-radius: 10px; background: transparent; color: var(--color-primary); font-size: 14px; font-weight: 700; }
.level-options { position: absolute; z-index: 30; top: calc(100% + 4px); right: 0; width: 128px; overflow: hidden; padding: 4px; border: 1px solid var(--color-border); border-radius: 12px; background: var(--color-surface); box-shadow: 0 12px 32px rgb(15 23 42 / 16%); }
.level-options button { display: grid; width: 100%; min-height: 42px; grid-template-columns: 22px 1fr; align-items: center; gap: 4px; padding: 0 8px; border: 0; border-radius: 9px; background: transparent; color: var(--color-text); text-align: left; }
.level-options button:active { background: var(--color-surface-muted); }
.level-options .active { color: var(--color-primary); font-weight: 700; }
.level-options .hidden { visibility: hidden; }
</style>