<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { use } from 'echarts/core'
import { PieChart } from 'echarts/charts'
import { LabelLayout } from 'echarts/features'
import { SVGRenderer } from 'echarts/renderers'
import VChart from 'vue-echarts'
import type { Category } from '@/domain/models/category'
import type { CategoryTotal } from '@/domain/services/statistics'
import { formatCents } from '@/domain/services/money'
import { colorOf } from '@/domain/services/category-color'
import { buildDonutOption, donutRadius } from './category-donut-options'

use([PieChart, LabelLayout, SVGRenderer])

const props = defineProps<{ items: CategoryTotal[]; allCategories: readonly Category[] }>()
const chartHost = ref<HTMLElement | null>(null)
const size = ref({ width: 328, height: 320 })
let resizeObserver: ResizeObserver | undefined

function itemColor(item: CategoryTotal): string {
  const category = props.allCategories.find((entry) => entry.id === item.categoryId)
  return category ? colorOf(category, props.allCategories) : '#1677ff'
}

const totalCents = computed(() => props.items.reduce((sum, item) => sum + item.amountCents, 0))
const amount = computed(() => formatCents(totalCents.value, false))
const centerWidth = computed(() => Math.max(60, donutRadius(size.value.width, size.value.height) * 0.64 * 2 - 18))
const amountFontSize = computed(() => Math.min(16, centerWidth.value / (amount.value.length * 0.64)))
const option = computed(() => buildDonutOption(props.items.map((item) => ({
  id: item.categoryId,
  name: item.name,
  value: item.amountCents,
  color: itemColor(item),
})), size.value.width, size.value.height))

// 空状态切换、分类切换和容器缩放时都重新测量；渲染与避让由 vue-echarts / ECharts 完成。
watch(chartHost, (host) => {
  resizeObserver?.disconnect()
  if (!host || typeof ResizeObserver === 'undefined') return
  resizeObserver = new ResizeObserver(([entry]) => {
    size.value = { width: entry.contentRect.width, height: entry.contentRect.height }
  })
  resizeObserver.observe(host)
}, { flush: 'post' })
onBeforeUnmount(() => resizeObserver?.disconnect())
</script>

<template>
  <div v-if="items.length" class="donut" role="img" :aria-label="`支出分类占比，共${items.length}个分类`">
    <div ref="chartHost" class="donut-canvas">
      <VChart :option="option" :init-options="{ renderer: 'svg' }" :update-options="{ notMerge: true }" autoresize />
      <div class="donut-center" :style="{ width: `${centerWidth}px` }">
        <span>总支出</span><strong class="money" :style="{ fontSize: `${amountFontSize}px` }">{{ amount }}</strong>
      </div>
    </div>
    <div class="donut-legend" role="list">
      <div v-for="item in items" :key="item.categoryId" role="listitem">
        <i :style="{ backgroundColor: itemColor(item) }" aria-hidden="true" />
        <span>{{ item.name }}</span>
        <small>{{ (item.ratio * 100).toFixed(1) }}%</small>
      </div>
    </div>
  </div>
  <p v-else class="empty">本期暂无支出数据</p>
</template>

<style scoped>
.donut-canvas { position: relative; height: clamp(320px, 80vw, 430px); }
.donut-center { position: absolute; top: 50%; left: 50%; display: flex; align-items: center; flex-direction: column; gap: 3px; color: var(--color-text-secondary); pointer-events: none; transform: translate(-50%, -50%); }
.donut-center span { font-size: 12px; }
.donut-center strong { color: var(--color-text); white-space: nowrap; }
.donut-legend { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px 12px; margin-top: 8px; }
.donut-legend div { display: grid; min-width: 0; grid-template-columns: 9px minmax(0, 1fr) auto; align-items: center; gap: 6px; }
.donut-legend i { width: 9px; height: 9px; border-radius: 50%; }
.donut-legend span { overflow: hidden; font-size: 13px; text-overflow: ellipsis; white-space: nowrap; }
.donut-legend small { color: var(--color-text-secondary); }
.empty { padding: 34px 0; color: var(--color-text-secondary); text-align: center; }
