<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight, ChartNoAxesCombined } from '@lucide/vue'
import { buildReport, groupTotalsByParent } from '@/domain/services/statistics'
import { formatCents } from '@/domain/services/money'
import { isWithin, localDateKey, rangeBounds } from '@/domain/services/date-range'
import { useAppStore } from '@/stores/app-store'
import AppDialog from '@/components/AppDialog.vue'
import IncomeExpenseChart from './IncomeExpenseChart.vue'
import CategoryDistribution from './CategoryDistribution.vue'
import CategoryDonutChart from './CategoryDonutChart.vue'
import CategoryLevelMenu from './CategoryLevelMenu.vue'

type ReportPeriod = 'month' | 'year'
/** 支出卡片的分类层级：child=二级分类（默认，与旧版一致），parent=一级分类聚合；占比图与分布列表联动共用 */
type CategoryLevel = 'child' | 'parent'

const store = useAppStore()
const period = ref<ReportPeriod>('month')
const reference = ref(new Date())
const pickerOpen = ref(false)
const pickerPeriod = ref<ReportPeriod>('month')
const pickerYear = ref(reference.value.getFullYear())
const pickerDecadeStart = ref(Math.floor(reference.value.getFullYear() / 10) * 10)
const expenseLevel = ref<CategoryLevel>('child')

const report = computed(() => buildReport(store.transactions, store.categories, period.value, reference.value, new Date()))
const hasData = computed(() => report.value.incomeCents > 0 || report.value.expenseCents > 0)
const rangeLabel = computed(() => period.value === 'month'
  ? `${reference.value.getFullYear()}年${String(reference.value.getMonth() + 1).padStart(2, '0')}月`
  : `${reference.value.getFullYear()}年`)
const activeTrendKey = computed(() => {
  const now = new Date()
  const isCurrent = period.value === 'month'
    ? reference.value.getFullYear() === now.getFullYear() && reference.value.getMonth() === now.getMonth()
    : reference.value.getFullYear() === now.getFullYear()
  if (isCurrent) return period.value === 'month'
    ? localDateKey(now)
    : `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`
  return report.value.trend.at(-1)?.key
})

onMounted(() => store.initialize())

/** 支出分类的数据源：二级用报表自带统计；一级把当期支出流水聚合到所属一级分类 */
const expenseDistributionItems = computed(() => {
  if (expenseLevel.value === 'child') return report.value.expenseCategories
  const bounds = rangeBounds(period.value, reference.value)
  const filtered = store.transactions.filter((record) => record.type === 'expense' && isWithin(record.bookedAt, bounds))
  return groupTotalsByParent(filtered, store.categories, 'expense')
})

/** 有流水的年月（`${年}-${月}`）与年份集合：选择器里给有数据的月份/年份标蓝点，一眼看出哪段时间记过账 */
const activeMonthKeys = computed(() => {
  const keys = new Set<string>()
  for (const item of store.transactions) {
    const date = new Date(item.bookedAt)
    keys.add(`${date.getFullYear()}-${date.getMonth()}`)
  }
  return keys
})
const activeYears = computed(() => new Set(store.transactions.map((item) => new Date(item.bookedAt).getFullYear())))
const hasMonthData = (month: number): boolean => activeMonthKeys.value.has(`${pickerYear.value}-${month}`)
const hasYearData = (year: number): boolean => activeYears.value.has(year)
const isMonthSelected = (month: number): boolean => period.value === 'month' && reference.value.getFullYear() === pickerYear.value && reference.value.getMonth() === month
const isYearSelected = (year: number): boolean => period.value === 'year' && reference.value.getFullYear() === year

function moveRange(amount: number): void {
  reference.value = period.value === 'month'
    ? new Date(reference.value.getFullYear(), reference.value.getMonth() + amount, 1)
    : new Date(reference.value.getFullYear() + amount, 0, 1)
}

function openPicker(): void {
  pickerPeriod.value = period.value
  pickerYear.value = reference.value.getFullYear()
  pickerDecadeStart.value = Math.floor(reference.value.getFullYear() / 10) * 10
  pickerOpen.value = true
}

function selectMonth(month: number): void {
  const now = new Date()
  period.value = 'month'
  reference.value = pickerYear.value === now.getFullYear() && month === now.getMonth()
    ? now
    : new Date(pickerYear.value, month, 1)
  pickerOpen.value = false
}

function selectYear(year: number): void {
  const now = new Date()
  period.value = 'year'
  reference.value = year === now.getFullYear() ? now : new Date(year, 0, 1)
  pickerOpen.value = false
}
</script>

<template>
  <!-- 日期选择器放到标题栏中间（App.vue 顶栏为本路由预留的 #topbar-center 挂载点） -->
  <Teleport to="#topbar-center">
    <nav class="range-nav" aria-label="报表时间范围">
      <button type="button" :aria-label="`上一${period === 'month' ? '月' : '年'}`" @click="moveRange(-1)"><ChevronLeft :size="22" /></button>
      <button class="range-current" type="button" :aria-label="`选择报表时间，当前${rangeLabel}`" @click="openPicker">
        <CalendarDays :size="17" aria-hidden="true" /><strong>{{ rangeLabel }}</strong><ChevronDown :size="17" aria-hidden="true" />
      </button>
      <button type="button" :aria-label="`下一${period === 'month' ? '月' : '年'}`" @click="moveRange(1)"><ChevronRight :size="22" /></button>
    </nav>
  </Teleport>

  <main class="page reports-page">
    <section v-if="!hasData" class="empty-report card">
      <ChartNoAxesCombined :size="48" aria-hidden="true" />
      <p>这段时间还没有数据</p>
    </section>

    <template v-else>
      <section class="totals card" aria-label="报表收支汇总">
        <div><span>总收入</span><strong class="income money">{{ formatCents(report.incomeCents) }}</strong></div>
        <div><span>总支出</span><strong class="expense money">-{{ formatCents(report.expenseCents) }}</strong></div>
        <div><span>结余</span><strong class="balance money">{{ formatCents(report.balanceCents) }}</strong></div>
      </section>

      <section class="card report-card">
        <div class="card-head">
          <h2>支出分类占比</h2>
          <CategoryLevelMenu v-model="expenseLevel" />
        </div>
        <CategoryDonutChart :items="expenseDistributionItems" :all-categories="store.categories" />
      </section>

      <section class="card report-card">
        <h2>收入来源</h2>
        <CategoryDistribution :items="report.incomeCategories" :all-categories="store.categories" empty-text="本期暂无收入数据" />
      </section>

      <section class="card report-card">
        <div class="card-head">
          <h2>支出分布</h2>
          <CategoryLevelMenu v-model="expenseLevel" />
        </div>
        <CategoryDistribution :items="expenseDistributionItems" :all-categories="store.categories" empty-text="本期暂无支出数据" />
      </section>

      <section class="card report-card">
        <h2>收支趋势</h2>
        <IncomeExpenseChart :points="report.trend" :initial-active-key="activeTrendKey" :title="`${rangeLabel}收支趋势`" />
      </section>
    </template>
  </main>

  <AppDialog :open="pickerOpen" title="选择时间" @close="pickerOpen = false">
    <div class="segmented picker-mode" aria-label="报表类型">
      <button type="button" :class="{ active: pickerPeriod === 'month' }" :aria-pressed="pickerPeriod === 'month'" @click="pickerPeriod = 'month'">月</button>
      <button type="button" :class="{ active: pickerPeriod === 'year' }" :aria-pressed="pickerPeriod === 'year'" @click="pickerPeriod = 'year'">年</button>
    </div>

    <div class="picker-page-nav">
      <button type="button" :aria-label="pickerPeriod === 'month' ? '上一年' : '上十年'" @click="pickerPeriod === 'month' ? pickerYear-- : pickerDecadeStart -= 10"><ChevronLeft :size="26" /></button>
      <strong>{{ pickerPeriod === 'month' ? `${pickerYear}年` : `${pickerDecadeStart}-${pickerDecadeStart + 9}年` }}</strong>
      <button type="button" :aria-label="pickerPeriod === 'month' ? '下一年' : '下十年'" @click="pickerPeriod === 'month' ? pickerYear++ : pickerDecadeStart += 10"><ChevronRight :size="26" /></button>
    </div>

    <div v-if="pickerPeriod === 'month'" class="picker-grid">
      <button v-for="month in 12" :key="month" type="button" :class="{ selected: isMonthSelected(month - 1) }" @click="selectMonth(month - 1)">
        <span>{{ pickerYear === new Date().getFullYear() && month - 1 === new Date().getMonth() ? '本月' : `${month}月` }}</span>
        <span v-if="hasMonthData(month - 1) && !isMonthSelected(month - 1)" class="data-dot" aria-hidden="true" />
      </button>
    </div>
    <div v-else class="picker-grid">
      <button v-for="offset in 10" :key="offset" type="button" :class="{ selected: isYearSelected(pickerDecadeStart + offset - 1) }" @click="selectYear(pickerDecadeStart + offset - 1)">
        <span>{{ pickerDecadeStart + offset - 1 === new Date().getFullYear() ? '本年' : `${pickerDecadeStart + offset - 1}年` }}</span>
        <span v-if="hasYearData(pickerDecadeStart + offset - 1) && !isYearSelected(pickerDecadeStart + offset - 1)" class="data-dot" aria-hidden="true" />
      </button>
    </div>
  </AppDialog>
</template>

<style scoped>
.reports-page { display: grid; gap: 20px; }
/* 顶栏日期选择器：透明融入标题栏（前后箭头 + 当前时间，点当前时间弹选择器） */
.range-nav { display: flex; width: 100%; align-items: center; justify-content: center; }
.range-nav > button { display: grid; width: 40px; height: 40px; place-items: center; border: 0; border-radius: 50%; background: transparent; color: var(--color-text-secondary); }
.range-nav .range-current { display: inline-flex; width: auto; min-width: 0; gap: 5px; color: var(--color-primary); }
.range-current strong { overflow: hidden; color: var(--color-text); font-size: 17px; text-overflow: ellipsis; white-space: nowrap; }
/* 汇总卡片三列：总收入 / 总支出 / 结余，列间细分割线；白底与报表其他卡片统一，金额走全局 income/expense 配色 */
.totals { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); padding: 18px 8px; }
.totals div { display: flex; min-width: 0; flex-direction: column; align-items: center; gap: 5px; padding: 0 4px; text-align: center; }
.totals div + div { border-left: 1px solid var(--color-border); }
.totals span { color: var(--color-text-secondary); font-size: 13px; }
.totals strong { max-width: 100%; overflow-wrap: anywhere; font-size: clamp(14px, 3.8vw, 19px); }
.totals .balance { color: var(--color-text); }
.report-card { padding: 16px; }
.report-card h2 { margin: 0 0 14px; font-size: 16px; }
/* 支出卡片头：标题 + 右侧分类层级下拉（下拉本体在 CategoryLevelMenu 组件里） */
.card-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.card-head h2 { margin: 0; }
.empty-report { display: grid; min-height: 320px; place-items: center; align-content: center; color: var(--color-text-secondary); text-align: center; }
.empty-report p { margin: 14px 0 0; }
.picker-mode { margin-bottom: 18px; }
.picker-page-nav { display: grid; grid-template-columns: 48px 1fr 48px; align-items: center; margin-bottom: 12px; text-align: center; }
.picker-page-nav button { display: grid; width: 48px; height: 48px; place-items: center; border: 0; border-radius: 50%; background: transparent; color: var(--color-text-secondary); }
.picker-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.picker-grid button { display: flex; min-height: 48px; flex-direction: column; align-items: center; justify-content: center; gap: 3px; padding: 0 3px; border: 0; border-radius: 12px; background: var(--color-surface-muted); color: var(--color-text-secondary); font-size: 14px; }
.picker-grid button.selected { background: var(--color-primary); color: white; font-weight: 700; }
/* 蓝点：该月份/年份有流水数据（选中项本身已高亮，不再显示） */
.data-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--color-primary); }
@media (max-width: 359px) { .picker-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
</style>
